# Shopping Cart Component with Redux Toolkit

Here's a complete React shopping cart component using Redux Toolkit for state management:

```jsx
// features/cartSlice.js
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  total: 0,
  subtotal: 0,
  tax: 0,
  shipping: 0,
  discounts: [],
  checkout: false,
};

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addToCart: (state, action) => {
      const item = action.payload;
      const existingItem = state.items.find(i => i.id === item.id);

      if (existingItem) {
        existingItem.quantity += item.quantity;
      } else {
        state.items.push({ ...item, quantity: item.quantity });
      }

      state.total = calculateTotal(state.items);
    },
    removeFromCart: (state, action) => {
      state.items = state.items.filter(item => item.id !== action.payload);
      state.total = calculateTotal(state.items);
    },
    updateQuantity: (state, action) => {
      const { id, quantity } = action.payload;
      const item = state.items.find(item => item.id === id);
      if (item) {
        item.quantity = quantity;
      }
      state.total = calculateTotal(state.items);
    },
    clearCart: (state) => {
      state.items = [];
      state.total = 0;
    },
    calculateTax: (state) => {
      state.tax = state.subtotal * 0.08; // 8% tax rate
    },
    applyDiscount: (state, action) => {
      const discount = action.payload;
      state.discounts.push(discount);
      state.total -= discount.amount;
    },
    checkout: (state) => {
      state.checkout = true;
    },
    resetCheckout: (state) => {
      state.checkout = false;
    },
  },
});

